// TESY Aquathermica Pro (BWWP) - RS485 sniffer -> MQTT / Home Assistant
// Input 1: Buffer (TCP stream from the Waveshare gateway, Modbus-TCP framing) -> decoded, output 1 = state
// Input 2: msg.topic === 'discover'                                         -> output 2 = MQTT discovery configs (retained)
//
// Temperature scaling: T[degC] = raw/2 - 30   (verified: reg 1104, 2020, 2021, 2025)
// Names containing "?" are NOT verified (hypotheses) -> rename here after checking.

const STATE_TOPIC = 'tesy/bwwp/state';
const DISC_PREFIX = 'homeassistant';
const DEV_ID = 'tesy_bwwp';
const HEARTBEAT_MS = 60000;   // also publish the state every 60 s without a change (because of expire_after)
const EXPIRE_S = 180;         // entity becomes 'unavailable' after 180 s without data

// type: 'temp' (raw/2-30) | 'raw' | 'bool' (raw != 0) | 'bit' | 'legio' | 'map' | 'dur_min' | 'dur_d'
