    { key: 'p1172', name: 'Reg 1172 - F13 - DC fan speed 5', reg: 1172, type: 'raw', on: false, diag: true },
    { key: 'p1011', name: 'Reg 1011 - Device on (0 = off)', reg: 1011, type: 'bool', icon: 'mdi:power', on: true },
    { key: 'p2015', name: 'Reg 2015 - Device on (mirror of reg 1011)', reg: 2015, type: 'bool', icon: 'mdi:power', on: false, diag: true },
    { key: 'p1129', name: 'Reg 1129 - Vacation active', reg: 1129, type: 'bool', icon: 'mdi:island', on: true },
    { key: 'p1143', name: 'Reg 1143 - No vacation (0 on vacation change)', reg: 1143, type: 'bool', icon: 'mdi:island', on: false, diag: true },
