    { key: 'p1076', name: 'Reg 1076 - H08? - Central control address (?)', reg: 1076, type: 'raw', on: false, diag: true },
    { key: 'p1077', name: 'Reg 1077 - (undocumented) 1', reg: 1077, type: 'raw', on: false, diag: true },
    { key: 'p1130', name: 'Reg 1130 - (vacation parameter?) 24', reg: 1130, type: 'raw', on: false, diag: true },
    { key: 'p1131', name: 'Reg 1131 - (vacation parameter?) 1', reg: 1131, type: 'raw', on: false, diag: true },
    { key: 'p1132', name: 'Reg 1132 - (vacation parameter?) 1', reg: 1132, type: 'raw', on: false, diag: true },
    { key: 'p1173', name: 'Reg 1173 - (fan parameter?) 30', reg: 1173, type: 'raw', on: false, diag: true },
    { key: 'p1174', name: 'Reg 1174 - (fan parameter?) 910', reg: 1174, type: 'raw', on: false, diag: true },
];
// Device clock: reg 1152 minute, 1153 hour, 1154 day, 1155 month, 1156 year (2 digits)
const CLOCK = { key: 'clock', name: 'Device clock' };

// ---------------------------------------------------------------- Discovery
if (!Buffer.isBuffer(msg.payload)) {
    if (msg.topic !== 'discover') return null;
    const device = {
        identifiers: [DEV_ID],
        name: 'TESY Aquathermica Pro',
        manufacturer: 'TESY',
        model: 'Aquathermica Pro (BWWP)'
    };
    const out = [];
    const base = (s, domain) => {
        const c = {
            name: s.name,
            unique_id: `${DEV_ID}_${s.key}`,
            default_entity_id: `${domain}.${DEV_ID}_${s.key}`,   // HA >= 2025.10 (object_id is removed from 2026.4)
            state_topic: STATE_TOPIC,
            value_template: `{{ value_json.${s.key} }}`,
            expire_after: EXPIRE_S,
            device: device
        };
        if (s.diag) c.entity_category = 'diagnostic';
        if (s.on === false) c.enabled_by_default = false;
        return c;
    };
    for (const s of SENSORS) {
        let domain = 'sensor';
        let cfg;
        if (s.type === 'bool' || s.type === 'bit' || s.type === 'legio') {
            domain = 'binary_sensor';
            cfg = base(s, domain);
            cfg.payload_on = 'ON';
            cfg.payload_off = 'OFF';
            cfg.icon = s.icon || 'mdi:toggle-switch-outline';
        } else {
            cfg = base(s, domain);
            if (s.type === 'temp') {
                cfg.device_class = 'temperature';
                cfg.unit_of_measurement = '°C';
                cfg.state_class = 'measurement';
                cfg.suggested_display_precision = 1;
            } else if (s.type === 'dur_min') {
                cfg.device_class = 'duration';
                cfg.unit_of_measurement = 'min';
                cfg.state_class = 'measurement';
            } else if (s.type === 'dur_d') {
                cfg.device_class = 'duration';
                cfg.unit_of_measurement = 'd';
                cfg.state_class = 'total_increasing';
            } else if (s.type === 'map') {
                cfg.device_class = 'enum';
                cfg.options = s.options;
            } else {
                cfg.state_class = 'measurement';
            }
        }
        out.push({ topic: `${DISC_PREFIX}/${domain}/${DEV_ID}/${s.key}/config`,
                   payload: JSON.stringify(cfg), retain: true, qos: 1 });
    }
    const cc = base({ key: CLOCK.key, name: CLOCK.name, diag: true, on: true }, 'sensor');
    cc.icon = 'mdi:clock-outline';
    out.push({ topic: `${DISC_PREFIX}/sensor/${DEV_ID}/${CLOCK.key}/config`,
               payload: JSON.stringify(cc), retain: true, qos: 1 });
    node.status({ fill: 'blue', shape: 'dot', text: `Discovery: ${out.length} entities` });
    return [null, out];
}

// ---------------------------------------------------------------- Decoding
// Reassemble the stream (MBAP: 2 byte TransId, 2 byte ProtoId=0, 2 byte length, then unit/FC/...)
let buf = Buffer.concat([context.get('buf') || Buffer.alloc(0), msg.payload]);
const regs = context.get('regs') || {};
let frames = 0;

while (buf.length >= 13) {
    if (buf.readUInt16BE(2) !== 0) { buf = buf.subarray(1); continue; }  // no MBAP header -> resync
    const total = 6 + buf.readUInt16BE(4);
    if (total < 13 || total > 300) { buf = buf.subarray(1); continue; }
    if (buf.length < total) break;                                        // frame incomplete
    const f = buf.subarray(0, total);
    buf = buf.subarray(total);

    const fc = f[7];
    if (fc !== 0x10) continue;                                            // only Write Multiple Registers (FC 0x10)
    const addr = f.readUInt16BE(8);
    const qty = f.readUInt16BE(10);
    const bc = f[12];
    if (bc !== qty * 2 || total !== 13 + bc) continue;                    // inconsistent
    for (let i = 0; i < qty; i++) regs[addr + i] = f.readUInt16BE(13 + 2 * i);
    frames++;
}
if (buf.length > 1024) buf = Buffer.alloc(0);                             // safety valve
context.set('buf', buf);
context.set('regs', regs);
if (!frames) return null;

// Build the state
const st = {};
for (const s of SENSORS) {
    const r = regs[s.reg];
    if (r === undefined) continue;
    if (s.type === 'temp') st[s.key] = Math.round((r / 2 - 30) * 10) / 10;
    else if (s.type === 'map') st[s.key] = (s.offReg && regs[s.offReg] === 0) ? 'Off' : ((s.map[r] !== undefined) ? s.map[r] : 'Unknown');
    else if (s.type === 'bit') st[s.key] = ((r >> s.bit) & 1) ? 'ON' : 'OFF';
    else if (s.type === 'legio') st[s.key] = (r !== 0) ? 'ON' : 'OFF';
    else if (s.type === 'bool') st[s.key] = r ? 'ON' : 'OFF';
    else {
      let v = r;
      if (s.mul) v *= s.mul;
      if (s.div) v /= s.div;
      st[s.key] = (s.prec === 0) ? Math.round(v) : Math.round(v * 10) / 10;   // prec: 0 -> whole number (fan speed)
    }
}
if (regs[1152] !== undefined && regs[1156] !== undefined) {
    const p = (n) => String(n).padStart(2, '0');
    st[CLOCK.key] = `${p(regs[1154])}.${p(regs[1155])}.20${p(regs[1156])} ${p(regs[1153])}:${p(regs[1152])}`;
}

// Publish only after all three blocks (1001/1091/2001) have been received once
if (Object.keys(st).length < SENSORS.length + 1) return null;

// Publish only on change or as heartbeat (the clock does not count as a change)
const cmp = Object.assign({}, st); delete cmp[CLOCK.key];
const sig = JSON.stringify(cmp);
const now = Date.now();
if (sig === context.get('sig') && now - (context.get('last') || 0) < HEARTBEAT_MS) return null;
context.set('sig', sig);
context.set('last', now);

node.status({ fill: 'green', shape: 'dot', text: `soll ${st.soll} / actual ${st.t2025} °C` });
return [{ topic: STATE_TOPIC, payload: JSON.stringify(st), retain: false, qos: 0 }, null];
